       target_application_id AS targetApplicationId,
       source_hash AS sourceHash
FROM mig_legacy_payment_application
WHERE environment = #{environment}
  AND source_uuid = #{sourceUuid}
  AND source_schema = #{sourceSchema}
  AND target_uuid = #{targetUuid}
  AND target_schema = #{targetSchema}
  AND deleted_at = 0
FOR SHARE

